/**
 * Generates a grid of points representing the Cartesian product
 * of intervals [var0, var1] and [var2, var3]
 * 
 * @param {number} var0 - Start of first interval
 * @param {number} var1 - End of first interval
 * @param {number} var2 - Start of second interval
 * @param {number} var3 - End of second interval
 * @param {number} stepsX - Number of points along x-axis (default: 10)
 * @param {number} stepsY - Number of points along y-axis (default: 10)
 * @returns {Array<Array<number>>} Grid of [x, y] coordinate pairs
 */
function generateCartesianGrid(var0, var1, var2, var3, stepsX = 10, stepsY = 10) {
  // Using Array methods for functional programming approach
  const xPoints = Array.from({ length: stepsX }, (_, i) => 
    var0 + (var1 - var0) * (i / (stepsX - 1))
