 * Simpler in-memory filter without external libraries
 */
function filterTableRowsSimple(tableData, conditions) {
  return tableData.filter(row => {
    return conditions.every(({ column, operator, value }) => {
      const cellValue = row[column];

      switch (operator) {
        case '=': return cellValue === value;
        case '!=': return cellValue !== value;
        case '>': return cellValue > value;
        case '<': return cellValue < value;
        case '>=': return cellValue >= value;
        case '<=': return cellValue <= value;
        case 'IN': return Array.isArray(value) ? value.includes(cellValue) : cellValue === value;
        case 'LIKE': return String(cellValue).includes(value);
        case 'BETWEEN': return cellValue >= value[0] && cellValue <= value[1];
        default: return true;
      }
    });
  });
}

// Quick example
