 * Reorders a key-to-sequence mapping so that entries are sorted in descending order
 * based on the highest number in each associated sequence.
 *
 * @param {Object} keyToSequence - A key-to-sequence mapping where each value is an array of numbers.
 * @returns {Object} A new object with keys reordered by the highest number in their sequence (descending).
 */
function sortByMaxSequence(keyToSequence) {
    // Extract keys and their max values
    const entries = Object.entries(keyToSequence);
    const maxValues = entries.map(([_, sequence]) => {
        if (!Array.isArray(sequence)) {
            throw new TypeError('All values must be arrays');
        }
        return Math.max(...sequence);
    });

