 * 
 * @example
 * // 3D distance
 * euclideanDistance([0, 0, 0], [1, 1, 1]); // Returns ~1.732
 * 
 * @example
 * // 5D distance
 * euclideanDistance([1, 2, 3, 4, 5], [2, 3, 4, 5, 6]); // Returns ~2.236
 */
function euclideanDistance(point1, point2) {
  // Validate inputs
  if (!Array.isArray(point1) || !Array.isArray(point2)) {
    throw new Error('Both points must be arrays');
  }

  if (point1.length === 0 || point2.length === 0) {
    throw new Error('Points cannot be empty');
  }

  if (point1.length !== point2.length) {
    throw new Error(
      `Points must have equal dimensions. Got ${point1.length} and ${point2.length}`
    );
  }

  // Calculate sum of squared differences using Decimal for precision
  const sumOfSquares = point1.reduce((sum, coord1, index) => {
    const coord2 = point2[index];
    const difference = new Decimal(coord1).minus(new Decimal(coord2));
    const squared = difference.times(difference);
    return sum.plus(squared);
  }, new Decimal(0));

  // Return the square root as a standard number
  return parseFloat(sumOfSquares.sqrt().toString());
}

