/**
 * Fetch all entries from a key-value collection whose keys fall between two boundary keys (inclusive)
 * @param {string} dbPath - Path to the SQLite database file
 * @param {string} tableName - Name of the table to query
 * @param {string} startKey - Lower boundary key (inclusive)
 * @param {string} endKey - Upper boundary key (inclusive)
 * @returns {Array<{key: string, value: any}>} Array of entries within the range
 */
function getRangeEntries(dbPath, tableName, startKey, endKey) {
  const db = new Database(dbPath);

  try {
    // Create table if it doesn't exist
    db.exec(`
      CREATE TABLE IF NOT EXISTS ${tableName} (
        key TEXT PRIMARY KEY,
        value TEXT NOT NULL
      )
    `);

    // Query entries where key is between startKey and endKey
    const stmt = db.prepare(`
      SELECT key, value FROM ${tableName}
      WHERE key >= ? AND key <= ?
      ORDER BY key ASC
    `);

    const results = stmt.all(startKey, endKey);

    // Parse JSON values back to original types
    return results.map(row => ({
      key: row.key,
      value: JSON.parse(row.value)
    }));

  } finally {
    db.close();
  }
}

