    .filter(segment => segment.isWordLike)
    .map(segment => segment.segment);

  // Normalize the target word to lowercase
  const normalizedWord = word.toLowerCase();

  // Count occurrences
  const count = wordSegments.reduce((accumulator, currentWord) => {
    return currentWord.toLowerCase() === normalizedWord 
      ? accumulator + 1 
      : accumulator;
  }, 0);

  return count;
}

