      headerMap.set(header, []);
    }
    headerMap.get(header).push(index);
  });

  // Convert to Danfo DataFrame for easier manipulation
  const df = new dfd.DataFrame(rows, { columns: headers });

  // Group columns by header name and sum them
  const result = {};

