/**
 * Iterate over each element of a 2D DataFrame along a specified axis
 * and apply a function to each element.
 * 
 * @param {dfd.DataFrame} df0 - Input 2D DataFrame
 * @param {number} axis - Axis along which to iterate (0 for rows, 1 for columns)
 * @param {Function} func - Function to apply to each element
 * @returns {Array} Array of results from applying func to each element
 */
function iterateAndApply(df0, axis, func) {
  const results = [];

  if (axis === 0) {
    // Iterate along rows (axis 0)
    df0.values.forEach((row, rowIndex) => {
      row.forEach((element, colIndex) => {
        results.push(func(element, rowIndex, colIndex));
      });
    });
  } else if (axis === 1) {
    // Iterate along columns (axis 1)
    df0.values[0].forEach((_, colIndex) => {
      df0.values.forEach((row, rowIndex) => {
        results.push(func(row[colIndex], rowIndex, colIndex));
      });
    });
  }

  return results;
}

// Example usage:
