 * Compares two sequences element-wise and returns a list of booleans
 * indicating whether elements at each position are equal.
 * 
 * @param {Array} seq1 - First input sequence
 * @param {Array} seq2 - Second input sequence
 * @returns {Array<boolean>} Array of booleans indicating equality at each position
 */
function elementwiseEquality(seq1, seq2) {
