 * and converts entries to floating-point values
 * @param {Array<Array>} table - A 2D array representing the table
 * @returns {Array<Array>} - The modified table with currency symbols removed
 */
function stripCurrencyFromPenultimateColumn(table) {
  if (!table || table.length === 0) {
    return table;
  }

  // Get the penultimate (second-to-last) column index
  const columnCount = table[0].length;
  if (columnCount < 2) {
    console.warn('Table must have at least 2 columns');
    return table;
  }

  const penultimateColumnIndex = columnCount - 2;

  // Process each row
  return table.map((row) => {
    const newRow = [...row];

    // Get the value from penultimate column
    const cellValue = newRow[penultimateColumnIndex];

    if (cellValue !== null && cellValue !== undefined) {
      // Remove common currency symbols and whitespace
      const cleanedValue = String(cellValue)
        .replace(/[$€¥£₹₽₩₪₨฿₱₡₵₴₸]/g, '')
        .trim();

      // Convert to float using Decimal for precision, then to Number
      try {
