```javascript
/**
 * Groups table rows by a specified column and sums all other columns
 * @param {Array<Object>} table - Array of objects representing table rows
 * @param {string} groupByColumn - The column name to group by (default: 'var0')
 * @returns {Array<Object>} Aggregated table with summed values
 */
function groupAndSumTable(table, groupByColumn = 'var0') {
  // Using Map for efficient grouping (part of JavaScript standard library)
  const grouped = new Map();

  for (const row of table) {
    const groupKey = row[groupByColumn];

    if (!grouped.has(groupKey)) {
      // Initialize with the grouping column
      grouped.set(groupKey, { [groupByColumn]: groupKey });
    }

    const groupedRow = grouped.get(groupKey);

    // Sum all numeric columns except the grouping column
    for (const [key, value] of Object.entries(row)) {
      if (key !== groupByColumn) {
        if (typeof value === 'number') {
          groupedRow[key] = (groupedRow[key] || 0) + value;
        }
      }
    }
  }

  // Convert Map to array and return
  return Array.from(grouped.values());
}

