  const {
    filter = null,
    orderBy = "count",
    order = "desc",
    limit = null,
    verbose = false,
  } = options;

  const client = new Anthropic();

  // Step 1: Count tuple occurrences
  const tupleCounts = new Map();

  for (const tuple of sequence) {
    const key = JSON.stringify(tuple);
    tupleCounts.set(key, (tupleCounts.get(key) || 0) + 1);
  }

  if (verbose) {
    console.log(`Total unique tuples found: ${tupleCounts.size}`);
  }

  // Step 2: Convert to array format for processing
  let results = Array.from(tupleCounts.entries()).map(([key, count]) => ({
    tuple: JSON.parse(key),
    count,
    stringified: key,
  }));

  // Step 3: Apply filtering using Claude for semantic understanding
  if (filter) {
    const prompt = `Given these tuples with their counts:
${JSON.stringify(results.map((r) => ({ tuple: r.tuple, count: r.count })), null, 2)}

