      const bStr = JSON.stringify(b.tuple);
      return order === "desc" ? bStr.localeCompare(aStr) : aStr.localeCompare(bStr);
    },
  };

  if (sortComparators[orderBy]) {
    results.sort(sortComparators[orderBy]);
  }

  if (verbose) {
    console.log(`Sorted by: ${orderBy} (${order}ending)`);
  }

  // Step 5: Apply limit
  if (limit && limit > 0) {
