    try {
        // Create the output table with the same schema as input plus two new columns
        await conn.query(`
            CREATE TABLE ${outputTable} AS
            SELECT
                * EXCEPT(${tupleColumn}),
                ${tupleColumn}[0] AS ${tupleColumn}_first,
                ${tupleColumn}[1] AS ${tupleColumn}_second
            FROM ${tableName}
        `);

        console.log(`Successfully split ${tupleColumn} into ${tupleColumn}_first and ${tupleColumn}_second`);
    } finally {
        // Clean up connection
        await conn.close();
    }
