 * Converts multiple lists into a two-dimensional table with column headers
 * @param {Array<Array>} data - Array of arrays containing row data
 * @param {Array<string>} headers - Array of column header names
 * @returns {Array<Object>} Array of objects with headers as keys
 */
function convertListsToTable(data, headers) {
  // Validate inputs
  if (!Array.isArray(data) || !Array.isArray(headers)) {
    throw new Error('Both data and headers must be arrays');
  }

  if (data.length === 0) {
    return [];
  }

  // Verify all rows have the same length as headers
  const headerCount = headers.length;
  data.forEach((row, index) => {
    if (!Array.isArray(row)) {
      throw new Error(`Row ${index} is not an array`);
    }
    if (row.length !== headerCount) {
      throw new Error(
        `Row ${index} has ${row.length} values, expected ${headerCount}`
      );
    }
  });

  // Convert to array of objects using headers as keys
  return data.map((row) => {
    const record = {};
    headers.forEach((header, index) => {
      record[header] = row[index];
    });
    return record;
  });
}

