      .map_elements(val => categoryToIndex.get(val), pl.UInt32)
      .alias(colName)
  );

  return {
    dataFrame: encodedDf,
    mapping: Object.fromEntries(categoryToIndex),
    reverseMapping: Object.fromEntries(
      Array.from(categoryToIndex.entries()).map(([cat, idx]) => [idx, cat])
    )
  };
}

