// Solutions: (√2, √2) and (-√2, -√2)
const equations1 = (x, y) => [
  x * x + y * y - 4,      // f1
  x - y                    // f2
];

const jacobian1 = (x, y) => [
  [2 * x, 2 * y],          // ∂f1/∂x, ∂f1/∂y
  [1, -1]                  // ∂f2/∂x, ∂f2/∂y
];

console.log("Example 1: x² + y² = 4 and x = y");
const result1 = solveNonlinearSystem(
  equations1,
  jacobian1,
  [1.5, 1.5],  // Initial guess near (√2, √2)
  { verbose: true }
);
console.log("Root:", result1.root);
console.log("Converged:", result1.converged, "\n");

// Example 2: Solve x*y - 1 = 0 and x^2 + y^2 - 5 = 0
// More complex nonlinear system
const equations2 = (x, y) => [
  x * y - 1,                // f1
  x * x + y * y - 5         // f2
];

const jacobian2 = (x, y) => [
  [y, x],                   // ∂f1/∂x, ∂f1/∂y
  [2 * x, 2 * y]            // ∂f2/∂x, ∂f2/∂y
];

console.log("Example 2: xy = 1 and x² + y² = 5");
