function segmentIntoIntervals(df0, str0, lst0) {
  // Validate inputs
  if (!Array.isArray(df0) || df0.length === 0) {
    throw new Error("df0 must be a non-empty array of objects.");
  }
  if (typeof str0 !== 'string') {
    throw new Error("str0 must be a column name (string).");
  }
  if (!Array.isArray(lst0) || lst0.length < 2) {
    throw new Error("lst0 must be an array of at least 2 boundary values.");
  }

  // Sort boundaries (ascending for numeric, lexicographic for strings)
  const sortedBoundaries = [...lst0].sort((a, b) =>
    typeof a === 'number' && typeof b === 'number'
      ? a - b
      : String(a).localeCompare(String(b))
  );

  // Helper: Determine segment for a value
  const getSegment = (value) => {
    const valueStr = String(value);
    for (let i = 0; i < sortedBoundaries.length - 1; i++) {
      const lower = sortedBoundaries[i];
      const upper = sortedBoundaries[i + 1];
      if ((typeof lower === 'number' && typeof upper === 'number'
           ? value >= lower && value < upper
           : valueStr >= lower && valueStr < upper)
         ) {
        return `${lower} <= value < ${upper}`;
      }
    }
    // Handle edge cases (values outside boundaries)
    if (value < sortedBoundaries[0]) return `value < ${sortedBoundaries[0]}`;
    if (value >= sortedBoundaries[sortedBoundaries.length - 1]) {
      return `value >= ${sortedBoundaries[sortedBoundaries.length - 1]}`;
    }
    return 'UNKNOWN';
