```javascript
/**
 * Removes rows from a table that contain duplicate values across specified columns
 * @param {Array<Object>} tableData - Array of objects representing table rows
 * @param {Array<string>} columnNames - Column names to check for duplicates
 * @param {Object} options - Configuration options
 * @param {boolean} options.keepFirst - Keep first occurrence (default: true)
 * @returns {Array<Object>} Table data with duplicate rows removed
 */
function removeDuplicateRows(tableData, columnNames, options = { keepFirst: true }) {
  // Input validation
  if (!Array.isArray(tableData) || tableData.length === 0) {
    return tableData;
  }

  if (!Array.isArray(columnNames) || columnNames.length === 0) {
    return tableData;
  }

  const seen = new Set();
  const result = [];

  for (const row of tableData) {
    // Create a composite key from specified columns
    const compositeKey = columnNames
      .map(col => String(row[col] ?? ''))
      .join('|');

    if (options.keepFirst) {
      // Keep only first occurrence
      if (!seen.has(compositeKey)) {
        seen.add(compositeKey);
        result.push(row);
      }
    } else {
      // Keep only last occurrence
      if (seen.has(compositeKey)) {
        // Remove previously added entry with same key
        const index = result.findIndex(r =>
          columnNames
            .map(col => String(r[col] ?? ''))
            .join('|') === compositeKey
        );
        if (index !== -1) {
          result.splice(index, 1);
        }
      }
      seen.add(compositeKey);
      result.push(row);
    }
  }

  return options.keepFirst ? result : result;
}

