  const iter2 = seq2[Symbol.iterator]();

  let result1, result2;
  while (
    !(result1 = iter1.next()).done &&
    !(result2 = iter2.next()).done
  ) {
    result.push([result1.value, result2.value]);
  }

  return result;
}

