```javascript
/**
 * Computes the dot product of two sequences
 * (sum of element-wise products)
 * 
 * @param {number[]} sequence1 - First sequence of numbers
 * @param {sequence2} number[] - Second sequence of numbers
 * @returns {number} The dot product result
 * @throws {Error} If sequences have different lengths
 */
function dotProduct(sequence1, sequence2) {
  // Validate inputs
  if (!Array.isArray(sequence1) || !Array.isArray(sequence2)) {
    throw new Error("Both inputs must be arrays");
  }

  if (sequence1.length !== sequence2.length) {
    throw new Error(
      `Sequences must have equal length. Got ${sequence1.length} and ${sequence2.length}`
    );
  }

  if (sequence1.length === 0) {
    return 0;
  }

  // Compute element-wise multiplication and sum
  return sequence1.reduce((sum, element, index) => {
    return sum + (element * sequence2[index]);
  }, 0);
}

// ============ EXAMPLES ============

