/**
 * Transforms array by tripling each element (n-1, n, n+1),
 * then zeros out every alternate element in the resulting sequence.
 * 
 * @param {number[]} arr0 - Input array of numbers
 * @returns {Promise<number[]>} Promise resolving to the transformed array
 */
async function transformAndZeroAlternates(arr0) {
  return from(arr0).pipe(
    // For each element, emit three values: n-1, n, n+1
    mergeMap(element => [element - 1, element, element + 1]),

    // Map with index to identify alternate positions
    map((value, index) => index % 2 === 1 ? 0 : value),

    // Collect all values into an array
    toArray()
  ).toPromise();
}

