  { id: 1, name: 'Alice', dept: 'Sales' },
  { id: 2, name: 'Bob', dept: 'IT' },
  { id: 3, name: 'Charlie', dept: 'HR' },
  { id: 4, name: 'Diana', dept: 'Sales' }
];

