 * @param {number} var0 - The column position (0-indexed) where to insert
 * @param {string} var1 - The name of the new column
 * @param {Array} var2 - The values for the new column
 * @returns {Object} - The modified DataFrame with the new column inserted
 */
function insertColumnAtPosition(df0, var0, var1, var2) {
  // Add the new column to the DataFrame
  df0.addColumn(var1, var2, { inplace: true });

  // Get current column names
  const columns = df0.columns;

  // Find the index of the newly added column
  const newColumnIndex = columns.indexOf(var1);

  // If the column is not already at the desired position, reorder
  if (newColumnIndex !== var0) {
    // Remove the column from its current position
    const reorderedColumns = columns.filter(col => col !== var1);

    // Insert it at the desired position
    reorderedColumns.splice(var0, 0, var1);

    // Reorder the DataFrame columns
    df0 = df0.loc({ columns: reorderedColumns });
  }

  return df0;
}

