      const values = indices.map(i => row[i]);

      // Try to sum if all numeric, otherwise concatenate
      if (values.every(v => typeof v === 'number')) {
        return values.reduce((sum, v) => sum + v, 0);
      } else {
        return values.join('');
      }
    });
  });

  return [uniqueHeaders, ...resultRows];
}

