 * @param {DataFrame} df0 - A Danfo.js DataFrame
 * @returns {Object} Object with averageRowIndex and averageColumnIndex
 */
function getAverageNonzeroPosition(df0) {
  const rowIndices = [];
  const colIndices = [];

