  const averageColumnIndex =
    colIndices.length > 0
      ? colIndices.reduce((a, b) => a + b, 0) / colIndices.length
      : null;

  return {
    averageRowIndex,
    averageColumnIndex,
    nonzeroCount: rowIndices.length,
  };
}

