 * @param {Array<Object>} data - Array of objects representing the data table
 * @param {Array<string>} keyColumns - Column names to group by
 * @returns {Array<Object>} Array with group combinations and their counts
 */
function groupCount(data, keyColumns) {
  // Create a Danfo.js DataFrame from the data
  const dfd = require('danfo-js-node');
  const df = new dfd.DataFrame(data);

  // Group by the specified columns and get the count
  const grouped = df.groupby(keyColumns).col(keyColumns).count();

  // Convert back to JavaScript array of objects
  return grouped.values.map((row, index) => {
    const result = {};
    keyColumns.forEach((col, colIndex) => {
      result[col] = row[colIndex];
    });
    result['count'] = grouped.values[index][keyColumns.length];
    return result;
  });
}

