/**
 * Divides specified columns by a reference column in a Danfo.js DataFrame
 * @param {Object} df0 - Danfo.js DataFrame
 * @param {string[]} columns_list0 - Array of column names to divide
 * @param {string} column_name0 - Column name to divide by (divisor)
 * @returns {Object} - New DataFrame with divided values
 */
async function divideColumnsByReference(df0, columns_list0, column_name0) {
  // Ensure Danfo.js is loaded
  const dfd = window.dfd || require('danfo-js-node');

  // Create a copy to avoid modifying original
  let result = df0.copy();

  // Get the divisor column as array
  const divisorValues = result[column_name0].values;

  // Divide each specified column
  columns_list0.forEach(colName => {
    if (!result.columns.includes(colName)) {
      throw new Error(`Column "${colName}" not found in DataFrame`);
    }

    // Get column values and divide
    const dividendValues = result[colName].values;
    const dividedValues = dividendValues.map((val, idx) => {
      const divisor = divisorValues[idx];
      // Handle division by zero
      return divisor === 0 ? NaN : val / divisor;
    });

    // Update column with divided values
    result[colName] = dividedValues;
  });

  return result;
}

// Example usage:
