/**
 * Converts a tabular dataset (DataFrame) into a list of dictionaries
 * @param {dfd.DataFrame} df - The input DataFrame
 * @returns {Array<Object>} Array of dictionaries with column names as keys
 */
function dataframeToListOfDicts(df) {
  const result = [];

  // Get column names
  const columns = df.columns;

  // Iterate through each row
  for (let i = 0; i < df.shape[0]; i++) {
