import dfd from "danfo-js-node";

function meanOfNonZeroIndices(df0) {
  /**
   * Computes the mean of the indices at which df0 contains non-zero values.
   * @param {dfd.Series} df0 - A Danfo.js Series
   * @returns {number} - The mean of indices containing non-zero values
   */

  // Get the values of the series
  const values = df0.values;

  // Find indices where values are non-zero
  const nonZeroIndices = values
    .map((val, idx) => (val !== 0 ? idx : null))
    .filter(idx => idx !== null);

  // Calculate the mean of those indices
  if (nonZeroIndices.length === 0) {
    return null; // or NaN if no non-zero values exist
  }

  const sum = nonZeroIndices.reduce((acc, idx) => acc + idx, 0);
  const mean = sum / nonZeroIndices.length;

  return mean;
}

