```javascript
/**
 * Compute the average of values in a tabular dataset
 * for specified rows and columns
 * @param {Array<Array>} data - 2D array representing the dataset
 * @param {Array<number>} rows - Array of row indices (var1)
 * @param {Array<number>} columns - Array of column indices (var0)
 * @returns {number} The average of specified cells
 */
function computeTableAverage(data, rows, columns) {
  const dfd = require('danfo-js'); // or import in ES6

  // Create DataFrame from data
  const df = new dfd.DataFrame(data);

  // Select specified rows and columns
  const selectedData = [];

  for (let rowIdx of rows) {
    for (let colIdx of columns) {
      const value = df.values[rowIdx][colIdx];
      if (typeof value === 'number') {
        selectedData.push(value);
      }
    }
  }

  // Calculate average
  if (selectedData.length === 0) return 0;
  const sum = selectedData.reduce((acc, val) => acc + val, 0);
  return sum / selectedData.length;
}

