    meanTable[i] = [];

    for (let j = 0; j < cols; j++) {
      // Collect corresponding entries from all tables
      const values = lst0.map(table => table[i][j]);

      // Compute mean using simple-statistics
      const mean = ss.mean(values);
      meanTable[i][j] = mean;
    }
  }

  return meanTable;
