import * as duckdb from '@duckdb/wasm';

/**
 * Adds aggregated columns (mean and sum) to a dataset grouped by var0
 * @param {Array<Object>} df0 - Input dataset with var0 and var1 columns
 * @returns {Promise<Array<Object>>} - Updated dataset with new aggregated columns
 */
async function addAggregatedColumns(df0) {
  // Initialize DuckDB
  const db = new duckdb.Database();
  const connection = await db.connect();

  try {
    // Register the input data as a table
    await connection.insertArrowTable(
      toArrowTable(df0),
      { name: 'input_data', replace: true }
    );

    // Create aggregated columns using SQL
    const query = `
      SELECT 
        *,
        AVG(var1) OVER (PARTITION BY var0) AS var1_mean,
        SUM(var1) OVER (PARTITION BY var0) AS var1_sum
      FROM input_data
    `;

    const result = await connection.query(query);
    const output = result.toArray();

    return output;
  } finally {
    await connection.close();
  }
}

/**
 * Helper function to convert array of objects to Arrow table format
 * @param {Array<Object>} data - Input data
 * @returns {Object} - Arrow table
 */
function toArrowTable(data) {
  if (data.length === 0) return null;

  const columns = {};
  const firstRow = data[0];

  // Initialize column arrays
  for (const key of Object.keys(firstRow)) {
    columns[key] = [];
  }

  // Populate columns
  for (const row of data) {
    for (const [key, value] of Object.entries(row)) {
      columns[key].push(value);
    }
  }

  return columns;
}

